import unittest
import sys
sys.path.insert(0, '.')
from runtime import module
m = module('.', 'engines/stylesheet_updates/engine.py')

class TestTransform(unittest.TestCase):
    def test_affected_intersection(self):
        out = m.transform({
            'dependencies': {'a': ['auto_save.interval', 'hints.min_chars'], 'b': ['aliases']},
            'changed': ['hints.min_chars'],
        }, None)
        self.assertEqual(out['dependencies'], {'a': ['auto_save.interval', 'hints.min_chars'], 'b': ['aliases']})
        self.assertEqual(out['affected'], ['a'])

    def test_sorted_multiple(self):
        out = m.transform({
            'dependencies': {'z': ['x'], 'a': ['x'], 'm': ['y']},
            'changed': ['x'],
        }, None)
        self.assertEqual(out['affected'], ['a', 'z'])

    def test_no_affected(self):
        out = m.transform({
            'dependencies': {'a': ['x']},
            'changed': ['y'],
        }, None)
        self.assertEqual(out['affected'], [])

if __name__ == '__main__':
    unittest.main()
