        got = m.transform(payload, None)
        self.assertEqual(got, {"t": ["a.b"]})

    def test_ignores_notconf_and_plain_text(self):
        payload = {
            "templates": {
                "t": "hello {{ notconf.x.y }} world {{ conf.k }}",
